WITH metrics_long AS (SELECT * FROM (SELECT id, customer_id, amount, discount, shipping_fee FROM orders) src UNPIVOT (metric_value FOR metric_name IN (amount AS AMOUNT, discount AS DISCOUNT_VAL, shipping_fee)) unp) SELECT customer_id, CASE WHEN metric_value >= 74 THEN 'HIGH' ELSE 'LOW' END AS metric_value_tier, MIN(metric_value) AS min_metric_value, COUNT(DISTINCT metric_name) AS distinct_metric_names FROM metrics_long GROUP BY customer_id, CASE WHEN metric_value >= 74 THEN 'HIGH' ELSE 'LOW' END;
